def search(index, query_tokens):
    if not query_tokens:
        return []
    postings = [index.get(t.lower(), []) for t in query_tokens]
    if any(len(p) == 0 for p in postings):
        return []
    postings.sort(key=len)
    result = set(postings[0])
    for p in postings[1:]:
        result &= set(p)
    return sorted(result)

class TrieNode:
    __slots__ = ("children", "is_end")
    def __init__(self):
        self.children = {}
        self.is_end = False

def build_trie(names):
    root = TrieNode()
    for name in names:
        node = root
        for ch in name:
            node = node.children.setdefault(ch, TrieNode())
        node.is_end = True
    return root

def prefix_search(root, prefix):
    node = root
    for ch in prefix:
        if ch not in node.children:
            return []
    node = node
    for ch in prefix:
        node = node.children[ch]
    results = []
    stack = [(node, prefix)]
    while stack:
        n, path = stack.pop()
        if n.is_end:
            results.append(path)
        for ch, child in n.children.items():
            stack.append((child, path + ch))
    return sorted(results)

