def edit_distance(a, b):
    m, n = len(a), len(b)
    dp = [[0]*(n+1) for _ in range(m+1)]
    for i in range(m+1):
        dp[i][0] = i
    for j in range(n+1):
        dp[0][j] = j
    for i in range(1, m+1):
        for j in range(1, n+1):
            cost = 0 if a[i-1] == b[j-1] else 1
            dp[i][j] = min(dp[i-1][j]+1, dp[i][j-1]+1, dp[i-1][j-1]+cost)
    return dp[m][n]

def fuzzy_search(dictionary, query, max_dist):
    candidates = [w for w in dictionary if abs(len(w)-len(query)) <= max_dist]
    return sorted(w for w in candidates if edit_distance(w, query) <= max_dist)

class DSU:
    def __init__(self, n):
        self.p = list(range(n))
    def find(self, x):
        while self.p[x] != x:
            self.p[x] = self.p[self.p[x]]
            x = self.p[x]
        return x
    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra != rb:
            self.p[ra] = rb

def normalize_email(e):
    return e.strip().lower()

def normalize_phone(p):
    return "".join(c for c in p if c.isdigit())

def find_duplicates(records):
    dsu = DSU(len(records))
    field_to_idx = {}
    for i, r in enumerate(records):
        keys = [("email", normalize_email(r["email"])), ("phone", normalize_phone(r["phone"]))]
        for field, val in keys:
            if not val:
                continue
            k = (field, val)
            if k in field_to_idx:
                dsu.union(i, field_to_idx[k])
            else:
                field_to_idx[k] = i
    groups = {}
    for i in range(len(records)):
        root = dsu.find(i)
        groups.setdefault(root, []).append(i)
    return sorted([sorted(g) for g in groups.values() if len(g) > 1])

