from collections import Counter

def build_tfidf_index(docs):
    N = len(docs)
    doc_tokens = [d.lower().split() for d in docs]
    df = Counter()
    for toks in doc_tokens:
        for t in set(toks):
            df[t] += 1
    idf = {t: math.log((N + 1) / (df[t] + 1)) + 1 for t in df}
    doc_vecs = []
    for toks in doc_tokens:
        tf = Counter(toks)
        vec = {t: (c / len(toks)) * idf[t] for t, c in tf.items()}
        doc_vecs.append(vec)
    return doc_vecs, idf

def rank_documents(doc_vecs, idf, query):
    q_tokens = query.lower().split()
    tf = Counter(q_tokens)
    q_vec = {t: (c / max(len(q_tokens), 1)) * idf.get(t, 0.0) for t, c in tf.items()}
    scores = []
    for doc_id, vec in enumerate(doc_vecs):
        score = sum(q_vec.get(t, 0.0) * w for t, w in vec.items())
        if score > 0:
            scores.append((doc_id, score))
    scores.sort(key=lambda x: (-x[1], x[0]))
    return scores

