def evaluate_boolean(index, universe, tokens):
    # tokens: list like ["cat", "AND", "dog", "OR", "NOT", "fish"]
    def term_set(tok):
        return index.get(tok.lower(), set())
    result = None
    op = "AND"
    i = 0
    while i < len(tokens):
        tok = tokens[i]
        if tok in ("AND", "OR"):
            op = tok
            i += 1
            continue
        if tok == "NOT":
            i += 1
            cur = universe - term_set(tokens[i])
        else:
            cur = term_set(tok)
        result = cur if result is None else (result & cur if op == "AND" else result | cur)
        i += 1
    return sorted(result) if result is not None else []

