def build_bm25_index(docs, k1=1.5, b=0.75):
    doc_tokens = [d.lower().split() for d in docs]
    N = len(docs)
    avgdl = sum(len(t) for t in doc_tokens) / N if N else 0
    df = Counter()
    for toks in doc_tokens:
        for t in set(toks):
            df[t] += 1
    return {"doc_tokens": doc_tokens, "N": N, "avgdl": avgdl, "df": df, "k1": k1, "b": b}

def bm25_score(index, query):
    doc_tokens, N, avgdl, df, k1, b = (index["doc_tokens"], index["N"], index["avgdl"],
                                        index["df"], index["k1"], index["b"])
    q_terms = query.lower().split()
    scores = []
    for doc_id, toks in enumerate(doc_tokens):
        tf = Counter(toks)
        dl = len(toks)
        score = 0.0
        for term in q_terms:
            if term not in tf:
                continue
            idf = math.log((N - df[term] + 0.5) / (df[term] + 0.5) + 1)
            freq = tf[term]
            score += idf * (freq * (k1 + 1)) / (freq + k1 * (1 - b + b * dl / avgdl))
        if score > 0:
            scores.append((doc_id, score))
    scores.sort(key=lambda x: (-x[1], x[0]))
    return scores

