def range_query(sorted_readings, start, end):
    timestamps = [r["timestamp"] for r in sorted_readings]
    lo = bisect.bisect_left(timestamps, start)
    hi = bisect.bisect_right(timestamps, end)
    return sorted_readings[lo:hi]

def build_kmp_table(pattern):
    table = [0] * len(pattern)
    k = 0
    for i in range(1, len(pattern)):
        while k > 0 and pattern[i] != pattern[k]:
            k = table[k-1]
        if pattern[i] == pattern[k]:
            k += 1
        table[i] = k
    return table

def kmp_search(text, pattern):
    if not pattern:
        return []
    table = build_kmp_table(pattern)
    positions = []
    k = 0
    for i, ch in enumerate(text):
        while k > 0 and ch != pattern[k]:
            k = table[k-1]
        if ch == pattern[k]:
            k += 1
        if k == len(pattern):
            positions.append(i - k + 1)
            k = table[k-1]
    return positions

def substring_search(docs, pattern):
    results = {}
    for i, d in enumerate(docs):
        pos = kmp_search(d, pattern)
        if pos:
            results[i] = pos
    return results

