def top_k_completions(root, prefix, k):
    node = root
    for ch in prefix:
        if ch not in node.children:
            return []
        node = node.children[ch]
    completions = []
    stack = [(node, prefix)]
    while stack:
        n, path = stack.pop()
        if n.freq > 0:
            completions.append((path, n.freq))
        for ch, child in n.children.items():
            stack.append((child, path + ch))
    completions.sort(key=lambda x: (-x[1], x[0]))
    return completions[:k]

def get_shingles(text, k=5):
    text = text.lower().replace(" ", "")
    if len(text) < k:
        return {text}
    return {text[i:i+k] for i in range(len(text) - k + 1)}

def jaccard(a, b):
    if not a and not b:
        return 1.0
    inter = len(a & b)
    union = len(a | b)
    return inter / union if union else 0.0

def find_near_duplicates(docs, k=5, threshold=0.5):
    shingle_sets = [get_shingles(d, k) for d in docs]
    pairs = []
    for i in range(len(docs)):
        for j in range(i+1, len(docs)):
            sim = jaccard(shingle_sets[i], shingle_sets[j])
            if sim >= threshold:
                pairs.append((i, j, round(sim, 4)))
    return pairs

