def search_groups(index, groups):
    if not groups:
        return []
    result = None
    for group in groups:
        union = set()
        for kw in group:
            union |= index.get(kw.lower(), set())
        result = union if result is None else (result & union)
        if not result:
            return []
    return sorted(result)

import bisect

def build_indices(products):
    name_index = {}
    for i, p in enumerate(products):
        for tok in set(p["name"].lower().split()):
            name_index.setdefault(tok, set()).add(i)
    category_index = {}
    for i, p in enumerate(products):
        category_index.setdefault(p["category"], set()).add(i)
    price_sorted = sorted(range(len(products)), key=lambda i: products[i]["price"])
    price_values = [products[i]["price"] for i in price_sorted]
    return name_index, category_index, price_sorted, price_values

def search(products, name_index, category_index, price_sorted, price_values,
           keyword=None, category=None, min_price=None, max_price=None):
    candidates = set(range(len(products)))
    if keyword:
        candidates &= name_index.get(keyword.lower(), set())
    if category:
        candidates &= category_index.get(category, set())
    if min_price is not None or max_price is not None:
        lo = bisect.bisect_left(price_values, min_price if min_price is not None else float("-inf"))
        hi = bisect.bisect_right(price_values, max_price if max_price is not None else float("inf"))
        candidates &= set(price_sorted[lo:hi])
    return sorted(candidates)

import string

def edits1(word):
    letters = string.ascii_lowercase
    splits = [(word[:i], word[i:]) for i in range(len(word)+1)]
    deletes = [a + b[1:] for a, b in splits if b]
    transposes = [a + b[1] + b[0] + b[2:] for a, b in splits if len(b) > 1]
    replaces = [a + c + b[1:] for a, b in splits if b for c in letters]
    inserts = [a + c + b for a, b in splits for c in letters]
    return set(deletes + transposes + replaces + inserts)

def known(words, dictionary_set):
    return {w for w in words if w in dictionary_set}

def correct(word, dictionary, freq):
    dictionary_set = set(dictionary)
    if word in dictionary_set:
        return [word]
    e1 = edits1(word)
    candidates = known(e1, dictionary_set)
    if not candidates:
        e2 = set()
        for w in e1:
            e2 |= edits1(w)
        candidates = known(e2, dictionary_set)
    ranked = sorted(candidates, key=lambda w: (-freq.get(w, 0), w))
    return ranked

import math

def build_grid(points, cell_size):
    grid = {}
    for i, (x, y) in enumerate(points):
        key = (int(x // cell_size), int(y // cell_size))
        grid.setdefault(key, []).append(i)
    return grid

def nearest_neighbor(points, grid, cell_size, query_point):
    qx, qy = query_point
    cx, cy = int(qx // cell_size), int(qy // cell_size)
    best = None
    best_dist = float("inf")
    radius = 0
    max_radius = max(1, len(points))
    while radius <= max_radius:
        found_any = False
        for dx in range(-radius, radius+1):
            for dy in range(-radius, radius+1):
                if max(abs(dx), abs(dy)) != radius:
                    continue
                cell = (cx+dx, cy+dy)
                if cell in grid:
                    found_any = True
                    for idx in grid[cell]:
                        px, py = points[idx]
                        d = math.hypot(px-qx, py-qy)
                        if d < best_dist:
                            best_dist = d
                            best = idx
        if best is not None and radius >= 1:
            break
        if not found_any and radius > 0 and best is not None:
            break
        radius += 1
        if radius > max_radius:
            break
    return best

