from collections import Counter

def normalize(text):
    return [t.strip(".,()").lower() for t in text.split() if t.strip(".,()")]

def build_title_index(papers):
    index = {}
    for i, p in enumerate(papers):
        for tok in set(normalize(p["title"])):
            index.setdefault(tok, []).append(i)
    return index

def match_citation(papers, index, citation_text):
    toks = normalize(citation_text)
    scores = Counter()
    for tok in toks:
        for paper_id in index.get(tok, []):
            scores[paper_id] += 1
    if not scores:
        return None
    best = max(scores.items(), key=lambda kv: (kv[1], -kv[0]))
    return best[0]

