def build_frequency_index(docs):
    index = {}
    for doc_id, text in enumerate(docs):
        counts = Counter(text.lower().split())
        for word, freq in counts.items():
            index.setdefault(word, []).append((doc_id, freq))
    return index

def top_k_documents(index, word, k):
    postings = index.get(word.lower(), [])
    ranked = sorted(postings, key=lambda p: (-p[1], p[0]))
    return ranked[:k]
